import numpy as np
from scipy import stats

MAX_DRIVERS = 5

def design(feats):
    # Identify potential drivers using correlation with outcome
    drivers = []
    columns = []
    products = []
    loadings = {}

    # Compute t-statistics for all non-clinical features
    tstats = []
    for i, fid in enumerate(feats.ids):
        if feats.types[i] == 'clinical':
            continue
        group0 = feats.x[feats.y==0, i]
        group1 = feats.x[feats.y==1, i]
        if len(group0) > 1 and len(group1) > 1:
            tstat, _ = stats.ttest_ind(group0, group1, equal_var=False)
            tstats.append((abs(tstat), fid, i))

    # Sort by t-statistic and take top 3
    tstats.sort(reverse=True)
    selected_indices = [idx for _, _, idx in tstats[:3]]

    # If no significant features found, return empty design
    if not selected_indices:
        return Design(drivers=(), columns=(), products=(), loadings={})

    # Use top feature as driver if it's significantly associated
    if tstats and tstats[0][0] > 1.5:
        drivers = [tstats[0][1]]

    # Add selected features to columns
    columns = [feats.ids[i] for i in selected_indices]

    # Create products between top features (max 3 pairs)
    for i in range(len(selected_indices)):
        for j in range(i+1, len(selected_indices)):
            if len(products) >= 3:
                break
            products.append((feats.ids[selected_indices[i]], feats.ids[selected_indices[j]]))

    # Simple weighted loading using standardized values
    for i, fid in enumerate(feats.ids):
        if i in selected_indices:
            loadings[fid] = 1.0

    return Design(drivers=tuple(drivers), columns=tuple(columns), products=tuple(products), loadings=loadings)

